        new TestRunningApplicationMonitor(sparkCluster, new NoopTimer());

    // Access the private runningApplications map via reflection and populate it
    Field runningAppsField =
        RunningApplicationMonitor.class.getDeclaredField("runningApplications");
    runningAppsField.setAccessible(true);

    @SuppressWarnings("unchecked")
    ConcurrentHashMap<NamespaceAndName, RunningAppInfo> map =
        new ConcurrentHashMap<>();
